def _unit_code(u):
    return {"ns": 0, "us": 1, "ms": 2, "s": 3}.get(u, -1)

_cases = [
    ("days365k", {"days": 365 * 1000}),
    ("days1e6", {"days": 10**6}),
    ("minutes1e9", {"minutes": 10**9}),
    ("days365k_us1", {"days": 365 * 1000, "microseconds": 1}),
    ("days365k_ms1", {"days": 365 * 1000, "milliseconds": 1}),
    ("days1e15", {"days": 10**15}),
]

for _name, _kw in _cases:
    try:
        _td = Timedelta(**_kw)
    except Exception:
        probe(_name + "_raised", 1.0)
        probe(_name + "_unit_code", -1.0)
        probe(_name + "_days", -1.0)
    else:
        probe(_name + "_raised", 0.0)
        probe(_name + "_unit_code", float(_unit_code(_td.unit)))
        probe(_name + "_days", float(_td.days))

